#include <cstdint>
#include <stdexcept>
#include <string>
#include <vector>

struct Score
{
    std::string name;
    int points;
};

std::vector<Score> rankScores(const std::vector<Score>& scores)
{
    std::vector<std::size_t> start(102, 0);                 // bucket b holds points 100 - b
    for (const auto& s : scores)
    {
        if (s.points < 0 || s.points > 100) throw std::invalid_argument("points must be 0 to 100");
        ++start[100 - s.points + 1];
    }
    for (std::size_t b = 1; b < start.size(); ++b) start[b] += start[b - 1];
    std::vector<Score> out(scores.size());
    for (const auto& s : scores) out[start[100 - s.points]++] = s;
    return out;
}

void radixSort(std::vector<std::uint32_t>& a)
{
    std::vector<std::uint32_t> buffer(a.size());
    for (int shift = 0; shift < 32; shift += 8)
    {
        std::size_t start[257] = {};
        for (std::uint32_t x : a) ++start[((x >> shift) & 0xFF) + 1];
        for (int b = 1; b < 257; ++b) start[b] += start[b - 1];
        for (std::uint32_t x : a) buffer[start[(x >> shift) & 0xFF]++] = x;
        a.swap(buffer);
    }
}

void radixSortSigned(std::vector<std::int32_t>& a)
{
    std::vector<std::uint32_t> u(a.size());
    for (std::size_t i = 0; i < a.size(); ++i) u[i] = static_cast<std::uint32_t>(a[i]) ^ 0x80000000u;
    radixSort(u);
    for (std::size_t i = 0; i < a.size(); ++i) a[i] = static_cast<std::int32_t>(u[i] ^ 0x80000000u);
}

void sortCodes(std::vector<std::string>& codes)
{
    if (codes.empty()) return;
    std::size_t length = codes[0].size();
    for (const auto& c : codes)
        if (c.size() != length) throw std::invalid_argument("codes must all have the same length");
    std::vector<std::string> buffer(codes.size());
    for (std::size_t pos = length; pos-- > 0;)
    {
        std::size_t start[257] = {};
        for (const auto& c : codes) ++start[static_cast<unsigned char>(c[pos]) + 1];
        for (int b = 1; b < 257; ++b) start[b] += start[b - 1];
        for (auto& c : codes) buffer[start[static_cast<unsigned char>(c[pos])]++] = std::move(c);
        codes.swap(buffer);
    }
}

