TEST("ranking scores") {
    std::vector<Score> s{ { "Ana", 72 }, { "Ben", 95 }, { "Cat", 72 }, { "Dev", 100 }, { "Eli", 0 }, { "Fay", 95 } };
    auto r = rankScores(s);
    std::string order;
    for (const auto& x : r) order += x.name + std::to_string(x.points) + " ";
    CHECK_EQ(order, std::string("Dev100 Ben95 Fay95 Ana72 Cat72 Eli0 "));
    CHECK(rankScores({}).empty());
    CHECK_THROWS(rankScores({ { "Zed", 101 } }));
    CHECK_THROWS(rankScores({ { "Zed", -1 } }));
}
TEST("radix sort") {
    std::vector<std::uint32_t> a{ 170, 45, 75, 90, 802, 24, 2, 66, 4294967295u, 0, 65536, 256 };
    radixSort(a);
    CHECK_EQ(a, (std::vector<std::uint32_t>{ 0, 2, 24, 45, 66, 75, 90, 170, 256, 802, 65536, 4294967295u }));
    std::vector<std::uint32_t> e;
    radixSort(e);
    CHECK(e.empty());
}
TEST("radix sort of 200,000 values") {
    std::vector<std::uint32_t> a(200000);
    std::uint32_t x = 2463534242u;
    for (auto& v : a) { x ^= x << 13; x ^= x >> 17; x ^= x << 5; v = x; }
    radixSort(a);
    bool ok = true;
    for (std::size_t i = 1; i < a.size(); ++i) ok = ok && a[i - 1] <= a[i];
    CHECK(ok);
}
TEST("signed values") {
    std::vector<std::int32_t> a{ 5, -3, 0, -2147483647 - 1, 2147483647, -1, 12, -100 };
    radixSortSigned(a);
    CHECK_EQ(a, (std::vector<std::int32_t>{ -2147483647 - 1, -100, -3, -1, 0, 5, 12, 2147483647 }));
}
TEST("codes of equal length") {
    std::vector<std::string> c{ "dab", "cab", "fad", "bad", "dad", "ebb", "ace", "add", "fed", "bed", "fee", "bee" };
    sortCodes(c);
    CHECK_EQ(c, (std::vector<std::string>{ "ace", "add", "bad", "bed", "bee", "cab", "dab", "dad", "ebb", "fad", "fed", "fee" }));
    std::vector<std::string> mixed{ "ab", "abc" };
    CHECK_THROWS(sortCodes(mixed));
    std::vector<std::string> none;
    sortCodes(none);
    CHECK(none.empty());
}

